-- Упражнения книги 17, глава 18 (oVirt). Файл строит scratchpad/ovirt/builder.py; после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-parse-answers', 0, 'func', 'Разбор файла ответов', 'Файл ответов engine-setup — текст из строк вида КЛЮЧ=тип:значение. Напишите функцию parse_answers(text) и верните словарь ключ → значение. Ключ — текст до первого «=». Тип — текст между этим «=» и следующим «:», значение — всё, что после этого «:» (оно может само содержать «:» и «=»). Типы: str — строка как есть; int — целое число; bool — True, если значение равно «True», иначе False; none — значение игнорируется, результат None. Пустые строки, строки, которые начинаются с «#» или «[», строки без «=» или без «:» после него и строки с неизвестным типом пропускаются. Пробелы по краям строки отбрасываются. Если ключ встретился повторно, побеждает последняя строка.', 'def parse_answers(text):
    pass
', 'text.splitlines(), strip(), затем split(''='', 1) и split('':'', 1); тип выбирайте через if/elif.', '{"func": "parse_answers", "tests": [{"args": ["[environment:default]\nOVESETUP_CONFIG/fqdn=str:engine.example.org\nOVESETUP_DB/port=int:5432\nOVESETUP_DWH/enable=bool:True"], "expected": {"OVESETUP_CONFIG/fqdn": "engine.example.org", "OVESETUP_DB/port": 5432, "OVESETUP_DWH/enable": true}}, {"args": ["# comment\n\n  A=str:x  \nnot a setting\nB=str\nC=float:1.5"], "expected": {"A": "x"}}, {"args": ["A/url=str:https://e:443/x=1"], "expected": {"A/url": "https://e:443/x=1"}}, {"args": ["K=int:1\nK=int:2"], "expected": {"K": 2}}, {"args": ["K=none:None\nF=bool:False\nE=str:"], "expected": {"K": null, "F": false, "E": ""}}, {"args": [""], "expected": {}}, {"args": ["X=bool:true"], "expected": {"X": false}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-rollup', 1, 'func', 'Свёртка показателей DWH', 'DWH копит минутные показатели и сворачивает их в часовые. Напишите функцию rollup(samples): samples — список кортежей (минута, значение), где минута — целое число минут от начала, значение — целое. Час отсчёта равен минута // 60. Верните список кортежей (час, количество, среднее, максимум) по всем часам, где есть показатели, по возрастанию часа. Среднее — sum/количество, округлённое до одного знака через round(x, 1). Входной список может быть неупорядоченным; для пустого списка верните пустой список.', 'def rollup(samples):
    pass
', 'Сгруппируйте значения в словаре час → список, потом пройдите по sorted(groups.items()).', '{"func": "rollup", "tests": [{"args": [[]], "expected": []}, {"args": [[{"__tuple__": [0, 10]}, {"__tuple__": [1, 20]}, {"__tuple__": [59, 30]}]], "expected": [{"__tuple__": [0, 3, 20.0, 30]}]}, {"args": [[{"__tuple__": [59, 10]}, {"__tuple__": [60, 20]}, {"__tuple__": [119, 40]}, {"__tuple__": [120, 5]}]], "expected": [{"__tuple__": [0, 1, 10.0, 10]}, {"__tuple__": [1, 2, 30.0, 40]}, {"__tuple__": [2, 1, 5.0, 5]}]}, {"args": [[{"__tuple__": [130, 7]}, {"__tuple__": [5, 1]}, {"__tuple__": [6, 2]}]], "expected": [{"__tuple__": [0, 2, 1.5, 2]}, {"__tuple__": [2, 1, 7.0, 7]}]}, {"args": [[{"__tuple__": [10, 1]}, {"__tuple__": [20, 2]}, {"__tuple__": [30, 2]}]], "expected": [{"__tuple__": [0, 3, 1.7, 2]}]}, {"args": [[{"__tuple__": [600, 0]}]], "expected": [{"__tuple__": [10, 1, 0.0, 0]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-run-command', 2, 'func', 'Команда с компенсацией', 'Модель команды менеджера. Команда — список шагов (имя, успех, откатываемый). Шаги выполняются по порядку. Успешный шаг пишет в журнал строку «do:имя». Первый неуспешный шаг пишет «fail:имя», после чего остальные шаги не выполняются, а уже выполненные шаги обрабатываются в обратном порядке: откатываемый шаг пишет «undo:имя», неоткатываемый — «skip:имя». Сам упавший шаг не обрабатывается. Напишите функцию run_command(steps): верните кортеж (статус, журнал), где статус — «FINISHED», если упавших шагов нет, и «FAILED» иначе; журнал — список строк.', 'def run_command(steps):
    pass
', 'Копите выполненные шаги в списке; при сбое пройдите по reversed(done).', '{"func": "run_command", "tests": [{"args": [[]], "expected": {"__tuple__": ["FINISHED", []]}}, {"args": [[{"__tuple__": ["db", true, true]}, {"__tuple__": ["host", true, false]}]], "expected": {"__tuple__": ["FINISHED", ["do:db", "do:host"]]}}, {"args": [[{"__tuple__": ["db", true, true]}, {"__tuple__": ["host", true, false]}, {"__tuple__": ["disk", false, true]}]], "expected": {"__tuple__": ["FAILED", ["do:db", "do:host", "fail:disk", "skip:host", "undo:db"]]}}, {"args": [[{"__tuple__": ["a", false, true]}, {"__tuple__": ["b", true, true]}]], "expected": {"__tuple__": ["FAILED", ["fail:a"]]}}, {"args": [[{"__tuple__": ["a", true, true]}, {"__tuple__": ["b", true, true]}, {"__tuple__": ["c", false, false]}, {"__tuple__": ["d", true, true]}]], "expected": {"__tuple__": ["FAILED", ["do:a", "do:b", "fail:c", "undo:b", "undo:a"]]}}, {"args": [[{"__tuple__": ["x", true, false]}]], "expected": {"__tuple__": ["FINISHED", ["do:x"]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-run-tree', 3, 'func', 'Дерево вложенных команд', 'Команды бывают вложенными. Узел дерева — кортеж (имя, успех, дети), где дети — список таких же узлов. Выполнение в глубину: узел сначала выполняет свою работу, потом по очереди дочерние команды. Узел с успехом пишет «do:имя» и считается выполненным; узел без успеха пишет «fail:имя» и всё выполнение немедленно прекращается (его дети и все следующие узлы не запускаются). Если выполнение прервано, компенсируются все ранее выполненные узлы — включая родителей упавшего узла — в порядке, обратном порядку «do», и каждый пишет «undo:имя». Напишите функцию run_tree(root): верните (статус, журнал), статус — «FINISHED» или «FAILED».', 'def run_tree(root):
    pass
', 'Рекурсивная функция run(node) возвращает True/False; список выполненных имён ведите в замыкании.', '{"func": "run_tree", "tests": [{"args": [{"__tuple__": ["A", true, []]}], "expected": {"__tuple__": ["FINISHED", ["do:A"]]}}, {"args": [{"__tuple__": ["A", true, [{"__tuple__": ["B", true, [{"__tuple__": ["C", true, []]}]]}, {"__tuple__": ["D", true, []]}]]}], "expected": {"__tuple__": ["FINISHED", ["do:A", "do:B", "do:C", "do:D"]]}}, {"args": [{"__tuple__": ["A", true, [{"__tuple__": ["B", true, []]}, {"__tuple__": ["C", false, []]}, {"__tuple__": ["D", true, []]}]]}], "expected": {"__tuple__": ["FAILED", ["do:A", "do:B", "fail:C", "undo:B", "undo:A"]]}}, {"args": [{"__tuple__": ["A", false, [{"__tuple__": ["B", true, []]}]]}], "expected": {"__tuple__": ["FAILED", ["fail:A"]]}}, {"args": [{"__tuple__": ["A", true, [{"__tuple__": ["B", true, [{"__tuple__": ["C", true, []]}, {"__tuple__": ["D", false, []]}, {"__tuple__": ["E", true, []]}]]}, {"__tuple__": ["F", true, []]}]]}], "expected": {"__tuple__": ["FAILED", ["do:A", "do:B", "do:C", "fail:D", "undo:C", "undo:B", "undo:A"]]}}, {"args": [{"__tuple__": ["A", true, [{"__tuple__": ["B", true, [{"__tuple__": ["C", true, []]}]]}, {"__tuple__": ["D", true, [{"__tuple__": ["E", false, []]}]]}]]}], "expected": {"__tuple__": ["FAILED", ["do:A", "do:B", "do:C", "do:D", "fail:E", "undo:D", "undo:C", "undo:B", "undo:A"]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-job-status', 4, 'func', 'Статус задания по шагам', 'Статус задания складывается из статусов шагов, а у шага могут быть подшаги. Шаг — кортеж (статус, подшаги), подшаги — список таких же шагов. Статусы упорядочены от лучшего к худшему: FINISHED < STARTED < ABORTED < FAILED. Статус шага — худший среди его собственного статуса и статусов всех его подшагов (на любой глубине). Напишите функцию job_status(steps): верните худший статус среди всех шагов верхнего уровня задания; для задания без шагов верните «STARTED».', 'def job_status(steps):
    pass
', 'Присвойте статусам числа и напишите рекурсивную функцию worst(step) с max.', '{"func": "job_status", "tests": [{"args": [[]], "expected": "STARTED"}, {"args": [[{"__tuple__": ["FINISHED", []]}]], "expected": "FINISHED"}, {"args": [[{"__tuple__": ["FINISHED", []]}, {"__tuple__": ["STARTED", []]}]], "expected": "STARTED"}, {"args": [[{"__tuple__": ["FINISHED", [{"__tuple__": ["FAILED", []]}]]}]], "expected": "FAILED"}, {"args": [[{"__tuple__": ["ABORTED", []]}, {"__tuple__": ["STARTED", []]}]], "expected": "ABORTED"}, {"args": [[{"__tuple__": ["FAILED", []]}, {"__tuple__": ["ABORTED", []]}]], "expected": "FAILED"}, {"args": [[{"__tuple__": ["FINISHED", [{"__tuple__": ["FINISHED", [{"__tuple__": ["STARTED", []]}]]}]]}]], "expected": "STARTED"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-audit-summary', 5, 'func', 'Сводка журнала аудита', 'Строка журнала аудита: «дата время ВАЖНОСТЬ КОД: сообщение», например «2026-10-30 12:01:00 ERROR VDS_FAILURE: Host h1 is non responsive». Важности от слабой к сильной: NORMAL, WARNING, ERROR, ALERT. Напишите функцию audit_summary(lines, min_severity): разбейте каждую строку на четыре части по пробелам (lines[i].split(None, 3)); строка пропускается, если частей меньше четырёх, важность не из списка или в четвёртой части нет «:». Код — текст четвёртой части до первого «:», без пробелов по краям. Верните кортеж (коды, счётчики): коды — список кодов в порядке строк для событий, чья важность не ниже min_severity; счётчики — словарь важность → сколько корректных строк с ней было (все корректные строки, независимо от min_severity; важности без строк в словарь не попадают).', 'def audit_summary(lines, min_severity):
    pass
', 'Порядок важности — словарь {''NORMAL'': 0, ...}; счётчик ведите через counts.get(sev, 0) + 1.', '{"func": "audit_summary", "tests": [{"args": [["2026-10-30 12:00:01 NORMAL USER_VDC_LOGIN: User admin logged in", "2026-10-30 12:00:05 WARNING VDS_HIGH_MEM_USE: Host h1 memory is high", "2026-10-30 12:01:00 ERROR VDS_FAILURE: Host h1 is non responsive", "garbage", "2026-10-30 12:02:00 ALERT ENGINE_NO_FULL_BACKUP: No full backup", "2026-10-30 12:03:00 DEBUG SOMETHING: unknown severity", "2026-10-30 12:04:00 NORMAL no colon here"], "WARNING"], "expected": {"__tuple__": [["VDS_HIGH_MEM_USE", "VDS_FAILURE", "ENGINE_NO_FULL_BACKUP"], {"NORMAL": 1, "WARNING": 1, "ERROR": 1, "ALERT": 1}]}}, {"args": [["2026-10-30 12:00:01 NORMAL USER_VDC_LOGIN: User admin logged in", "2026-10-30 12:00:05 WARNING VDS_HIGH_MEM_USE: Host h1 memory is high", "2026-10-30 12:01:00 ERROR VDS_FAILURE: Host h1 is non responsive", "garbage", "2026-10-30 12:02:00 ALERT ENGINE_NO_FULL_BACKUP: No full backup", "2026-10-30 12:03:00 DEBUG SOMETHING: unknown severity", "2026-10-30 12:04:00 NORMAL no colon here"], "NORMAL"], "expected": {"__tuple__": [["USER_VDC_LOGIN", "VDS_HIGH_MEM_USE", "VDS_FAILURE", "ENGINE_NO_FULL_BACKUP"], {"NORMAL": 1, "WARNING": 1, "ERROR": 1, "ALERT": 1}]}}, {"args": [["2026-10-30 12:00:01 NORMAL USER_VDC_LOGIN: User admin logged in", "2026-10-30 12:00:05 WARNING VDS_HIGH_MEM_USE: Host h1 memory is high", "2026-10-30 12:01:00 ERROR VDS_FAILURE: Host h1 is non responsive", "garbage", "2026-10-30 12:02:00 ALERT ENGINE_NO_FULL_BACKUP: No full backup", "2026-10-30 12:03:00 DEBUG SOMETHING: unknown severity", "2026-10-30 12:04:00 NORMAL no colon here"], "ALERT"], "expected": {"__tuple__": [["ENGINE_NO_FULL_BACKUP"], {"NORMAL": 1, "WARNING": 1, "ERROR": 1, "ALERT": 1}]}}, {"args": [[], "NORMAL"], "expected": {"__tuple__": [[], {}]}}, {"args": [["2026-10-30 12:00:00 ERROR A: x", "2026-10-30 12:00:01 ERROR B: y: z", "2026-10-30 12:00:02 NORMAL C: w"], "ERROR"], "expected": {"__tuple__": [["A", "B"], {"ERROR": 2, "NORMAL": 1}]}}, {"args": [["2026-10-30 12:00:00 ERROR  SPACED : msg"], "NORMAL"], "expected": {"__tuple__": [["SPACED"], {"ERROR": 1}]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-trace-correlation', 6, 'func', 'След команды в engine.log', 'Строка engine.log в нашей модели: «дата время УРОВЕНЬ логгер поток [cid] сообщение», все поля до сообщения разделены пробелами и сами пробелов не содержат; сообщение — остаток строки. Напишите функцию trace_correlation(lines, cid): разбейте каждую строку lines[i].split(None, 6); пропустите строку, если частей меньше семи или шестая часть (индекс 5) не заключена в квадратные скобки. Строка относится к команде, если текст внутри скобок равен cid. Верните кортеж (записи, первая_ошибка): записи — список кортежей (уровень, сообщение) для строк команды в порядке журнала (сообщение без пробелов по краям); первая_ошибка — сообщение первой записи с уровнем ERROR или пустая строка, если таких нет.', 'def trace_correlation(lines, cid):
    pass
', 'tag = parts[5]; проверьте tag[0] == ''['' и tag[-1] == '']'', сравнивайте tag[1:-1] с cid.', '{"func": "trace_correlation", "tests": [{"args": [["2026-10-30 12:00:01,100 INFO ovirt.CommandBase task-1 [a1] Running command: AddDiskCommand", "2026-10-30 12:00:01,200 INFO ovirt.CommandBase task-2 [b2] Running command: StartVmCommand", "2026-10-30 12:00:02,300 INFO ovirt.VdsBroker task-1 [a1] START, CreateVolume", "short line", "2026-10-30 12:00:03,400 ERROR ovirt.VdsBroker task-1 [a1] Command failed: low space", "2026-10-30 12:00:03,500 WARN ovirt.Other task-1 a1 no brackets here", "2026-10-30 12:00:04,600 ERROR ovirt.Other task-3 [a1] Second error"], "a1"], "expected": {"__tuple__": [[{"__tuple__": ["INFO", "Running command: AddDiskCommand"]}, {"__tuple__": ["INFO", "START, CreateVolume"]}, {"__tuple__": ["ERROR", "Command failed: low space"]}, {"__tuple__": ["ERROR", "Second error"]}], "Command failed: low space"]}}, {"args": [["2026-10-30 12:00:01,100 INFO ovirt.CommandBase task-1 [a1] Running command: AddDiskCommand", "2026-10-30 12:00:01,200 INFO ovirt.CommandBase task-2 [b2] Running command: StartVmCommand", "2026-10-30 12:00:02,300 INFO ovirt.VdsBroker task-1 [a1] START, CreateVolume", "short line", "2026-10-30 12:00:03,400 ERROR ovirt.VdsBroker task-1 [a1] Command failed: low space", "2026-10-30 12:00:03,500 WARN ovirt.Other task-1 a1 no brackets here", "2026-10-30 12:00:04,600 ERROR ovirt.Other task-3 [a1] Second error"], "b2"], "expected": {"__tuple__": [[{"__tuple__": ["INFO", "Running command: StartVmCommand"]}], ""]}}, {"args": [["2026-10-30 12:00:01,100 INFO ovirt.CommandBase task-1 [a1] Running command: AddDiskCommand", "2026-10-30 12:00:01,200 INFO ovirt.CommandBase task-2 [b2] Running command: StartVmCommand", "2026-10-30 12:00:02,300 INFO ovirt.VdsBroker task-1 [a1] START, CreateVolume", "short line", "2026-10-30 12:00:03,400 ERROR ovirt.VdsBroker task-1 [a1] Command failed: low space", "2026-10-30 12:00:03,500 WARN ovirt.Other task-1 a1 no brackets here", "2026-10-30 12:00:04,600 ERROR ovirt.Other task-3 [a1] Second error"], "zz"], "expected": {"__tuple__": [[], ""]}}, {"args": [[], "a1"], "expected": {"__tuple__": [[], ""]}}, {"args": [["2026-10-30 12:00:00,000 WARN x t [c] only warn", "2026-10-30 12:00:01,000 ERROR x t [c] boom [c]"], "c"], "expected": {"__tuple__": [[{"__tuple__": ["WARN", "only warn"]}, {"__tuple__": ["ERROR", "boom [c]"]}], "boom [c]"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-effective-setting', 7, 'func', 'Эффективная настройка', 'Значение настройки ищется на трёх уровнях, от самого близкого. Сначала настройки машины vm (словарь ключ → значение): если ключ есть, берём его. Затем настройки кластера cluster (словарь): если ключ есть, берём его. Затем глобальные ключи global_cfg: словарь ключ → словарь версия → значение, где версия «general» означает значение по умолчанию для любых версий. Для глобального ключа берём значение для версии совместимости cver, а если такой версии нет — значение «general»; если и его нет или ключа нет вовсе, результат None. Значение, равное 0, False или пустой строке, всё равно считается заданным. Напишите функцию effective(key, cver, vm, cluster, global_cfg).', 'def effective(key, cver, vm, cluster, global_cfg):
    pass
', 'Проверяйте наличие через `key in vm`, а не через truthiness значения.', '{"func": "effective", "tests": [{"args": ["MaxNumOfVmCpus", "4.6", {}, {}, {"MaxNumOfVmCpus": {"4.6": 256, "general": 128}, "SessionTimeout": {"general": 30}, "MigrationBandwidth": {"4.7": 100}}], "expected": 256}, {"args": ["MaxNumOfVmCpus", "4.7", {}, {}, {"MaxNumOfVmCpus": {"4.6": 256, "general": 128}, "SessionTimeout": {"general": 30}, "MigrationBandwidth": {"4.7": 100}}], "expected": 128}, {"args": ["SessionTimeout", "4.7", {}, {"SessionTimeout": 60}, {"MaxNumOfVmCpus": {"4.6": 256, "general": 128}, "SessionTimeout": {"general": 30}, "MigrationBandwidth": {"4.7": 100}}], "expected": 60}, {"args": ["SessionTimeout", "4.7", {"SessionTimeout": 0}, {"SessionTimeout": 60}, {"MaxNumOfVmCpus": {"4.6": 256, "general": 128}, "SessionTimeout": {"general": 30}, "MigrationBandwidth": {"4.7": 100}}], "expected": 0}, {"args": ["MigrationBandwidth", "4.6", {}, {}, {"MaxNumOfVmCpus": {"4.6": 256, "general": 128}, "SessionTimeout": {"general": 30}, "MigrationBandwidth": {"4.7": 100}}], "expected": null}, {"args": ["MigrationBandwidth", "4.7", {}, {}, {"MaxNumOfVmCpus": {"4.6": 256, "general": 128}, "SessionTimeout": {"general": 30}, "MigrationBandwidth": {"4.7": 100}}], "expected": 100}, {"args": ["Unknown", "4.7", {}, {}, {"MaxNumOfVmCpus": {"4.6": 256, "general": 128}, "SessionTimeout": {"general": 30}, "MigrationBandwidth": {"4.7": 100}}], "expected": null}, {"args": ["MaxNumOfVmCpus", "4.6", {"MaxNumOfVmCpus": 64}, {"MaxNumOfVmCpus": 32}, {"MaxNumOfVmCpus": {"4.6": 256, "general": 128}, "SessionTimeout": {"general": 30}, "MigrationBandwidth": {"4.7": 100}}], "expected": 64}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-can', 8, 'func', 'Проверка прав с наследованием', 'Модель прав. Словарь model содержит: parents — словарь объект → родитель (у корня родителя в словаре нет; циклов нет); roles — словарь роль → список действий (действие «*» разрешает любое); groups — словарь пользователь → список его групп; perms — список разрешений (субъект, роль, объект), где субъект — имя пользователя или группы. Напишите функцию can(user, action, obj, model): верните True, если есть разрешение, у которого субъект — это user или одна из его групп, объект — это obj или любой его предок (по цепочке parents), а роль (если она есть в roles) разрешает действие action. Неизвестная роль не разрешает ничего. Иначе верните False.', 'def can(user, action, obj, model):
    pass
', 'Постройте цепочку obj, parents[obj], ... в цикле while; затем перебирайте perms.', '{"func": "can", "tests": [{"args": ["alice", "vm.start", "vm1", {"parents": {"dc1": "system", "cl1": "dc1", "cl2": "dc1", "h1": "cl1", "vm1": "cl1", "vm2": "cl2", "h2": "cl2", "dc2": "system", "cl3": "dc2", "vm3": "cl3"}, "roles": {"SuperUser": ["*"], "ClusterAdmin": ["vm.start", "vm.stop", "host.maintenance"], "UserRole": ["vm.start"], "StorageAdmin": ["domain.create"]}, "groups": {"alice": ["ops"], "bob": ["devs", "ops"]}, "perms": [{"__tuple__": ["alice", "ClusterAdmin", "cl1"]}, {"__tuple__": ["devs", "UserRole", "vm3"]}, {"__tuple__": ["carol", "SuperUser", "system"]}, {"__tuple__": ["ops", "StorageAdmin", "dc2"]}, {"__tuple__": ["erin", "Ghost", "system"]}]}], "expected": true}, {"args": ["alice", "vm.start", "vm2", {"parents": {"dc1": "system", "cl1": "dc1", "cl2": "dc1", "h1": "cl1", "vm1": "cl1", "vm2": "cl2", "h2": "cl2", "dc2": "system", "cl3": "dc2", "vm3": "cl3"}, "roles": {"SuperUser": ["*"], "ClusterAdmin": ["vm.start", "vm.stop", "host.maintenance"], "UserRole": ["vm.start"], "StorageAdmin": ["domain.create"]}, "groups": {"alice": ["ops"], "bob": ["devs", "ops"]}, "perms": [{"__tuple__": ["alice", "ClusterAdmin", "cl1"]}, {"__tuple__": ["devs", "UserRole", "vm3"]}, {"__tuple__": ["carol", "SuperUser", "system"]}, {"__tuple__": ["ops", "StorageAdmin", "dc2"]}, {"__tuple__": ["erin", "Ghost", "system"]}]}], "expected": false}, {"args": ["alice", "vm.start", "cl1", {"parents": {"dc1": "system", "cl1": "dc1", "cl2": "dc1", "h1": "cl1", "vm1": "cl1", "vm2": "cl2", "h2": "cl2", "dc2": "system", "cl3": "dc2", "vm3": "cl3"}, "roles": {"SuperUser": ["*"], "ClusterAdmin": ["vm.start", "vm.stop", "host.maintenance"], "UserRole": ["vm.start"], "StorageAdmin": ["domain.create"]}, "groups": {"alice": ["ops"], "bob": ["devs", "ops"]}, "perms": [{"__tuple__": ["alice", "ClusterAdmin", "cl1"]}, {"__tuple__": ["devs", "UserRole", "vm3"]}, {"__tuple__": ["carol", "SuperUser", "system"]}, {"__tuple__": ["ops", "StorageAdmin", "dc2"]}, {"__tuple__": ["erin", "Ghost", "system"]}]}], "expected": true}, {"args": ["alice", "vm.start", "dc1", {"parents": {"dc1": "system", "cl1": "dc1", "cl2": "dc1", "h1": "cl1", "vm1": "cl1", "vm2": "cl2", "h2": "cl2", "dc2": "system", "cl3": "dc2", "vm3": "cl3"}, "roles": {"SuperUser": ["*"], "ClusterAdmin": ["vm.start", "vm.stop", "host.maintenance"], "UserRole": ["vm.start"], "StorageAdmin": ["domain.create"]}, "groups": {"alice": ["ops"], "bob": ["devs", "ops"]}, "perms": [{"__tuple__": ["alice", "ClusterAdmin", "cl1"]}, {"__tuple__": ["devs", "UserRole", "vm3"]}, {"__tuple__": ["carol", "SuperUser", "system"]}, {"__tuple__": ["ops", "StorageAdmin", "dc2"]}, {"__tuple__": ["erin", "Ghost", "system"]}]}], "expected": false}, {"args": ["bob", "vm.start", "vm3", {"parents": {"dc1": "system", "cl1": "dc1", "cl2": "dc1", "h1": "cl1", "vm1": "cl1", "vm2": "cl2", "h2": "cl2", "dc2": "system", "cl3": "dc2", "vm3": "cl3"}, "roles": {"SuperUser": ["*"], "ClusterAdmin": ["vm.start", "vm.stop", "host.maintenance"], "UserRole": ["vm.start"], "StorageAdmin": ["domain.create"]}, "groups": {"alice": ["ops"], "bob": ["devs", "ops"]}, "perms": [{"__tuple__": ["alice", "ClusterAdmin", "cl1"]}, {"__tuple__": ["devs", "UserRole", "vm3"]}, {"__tuple__": ["carol", "SuperUser", "system"]}, {"__tuple__": ["ops", "StorageAdmin", "dc2"]}, {"__tuple__": ["erin", "Ghost", "system"]}]}], "expected": true}, {"args": ["bob", "vm.stop", "vm3", {"parents": {"dc1": "system", "cl1": "dc1", "cl2": "dc1", "h1": "cl1", "vm1": "cl1", "vm2": "cl2", "h2": "cl2", "dc2": "system", "cl3": "dc2", "vm3": "cl3"}, "roles": {"SuperUser": ["*"], "ClusterAdmin": ["vm.start", "vm.stop", "host.maintenance"], "UserRole": ["vm.start"], "StorageAdmin": ["domain.create"]}, "groups": {"alice": ["ops"], "bob": ["devs", "ops"]}, "perms": [{"__tuple__": ["alice", "ClusterAdmin", "cl1"]}, {"__tuple__": ["devs", "UserRole", "vm3"]}, {"__tuple__": ["carol", "SuperUser", "system"]}, {"__tuple__": ["ops", "StorageAdmin", "dc2"]}, {"__tuple__": ["erin", "Ghost", "system"]}]}], "expected": false}, {"args": ["carol", "domain.create", "h2", {"parents": {"dc1": "system", "cl1": "dc1", "cl2": "dc1", "h1": "cl1", "vm1": "cl1", "vm2": "cl2", "h2": "cl2", "dc2": "system", "cl3": "dc2", "vm3": "cl3"}, "roles": {"SuperUser": ["*"], "ClusterAdmin": ["vm.start", "vm.stop", "host.maintenance"], "UserRole": ["vm.start"], "StorageAdmin": ["domain.create"]}, "groups": {"alice": ["ops"], "bob": ["devs", "ops"]}, "perms": [{"__tuple__": ["alice", "ClusterAdmin", "cl1"]}, {"__tuple__": ["devs", "UserRole", "vm3"]}, {"__tuple__": ["carol", "SuperUser", "system"]}, {"__tuple__": ["ops", "StorageAdmin", "dc2"]}, {"__tuple__": ["erin", "Ghost", "system"]}]}], "expected": true}, {"args": ["bob", "domain.create", "vm3", {"parents": {"dc1": "system", "cl1": "dc1", "cl2": "dc1", "h1": "cl1", "vm1": "cl1", "vm2": "cl2", "h2": "cl2", "dc2": "system", "cl3": "dc2", "vm3": "cl3"}, "roles": {"SuperUser": ["*"], "ClusterAdmin": ["vm.start", "vm.stop", "host.maintenance"], "UserRole": ["vm.start"], "StorageAdmin": ["domain.create"]}, "groups": {"alice": ["ops"], "bob": ["devs", "ops"]}, "perms": [{"__tuple__": ["alice", "ClusterAdmin", "cl1"]}, {"__tuple__": ["devs", "UserRole", "vm3"]}, {"__tuple__": ["carol", "SuperUser", "system"]}, {"__tuple__": ["ops", "StorageAdmin", "dc2"]}, {"__tuple__": ["erin", "Ghost", "system"]}]}], "expected": true}, {"args": ["dave", "vm.start", "vm1", {"parents": {"dc1": "system", "cl1": "dc1", "cl2": "dc1", "h1": "cl1", "vm1": "cl1", "vm2": "cl2", "h2": "cl2", "dc2": "system", "cl3": "dc2", "vm3": "cl3"}, "roles": {"SuperUser": ["*"], "ClusterAdmin": ["vm.start", "vm.stop", "host.maintenance"], "UserRole": ["vm.start"], "StorageAdmin": ["domain.create"]}, "groups": {"alice": ["ops"], "bob": ["devs", "ops"]}, "perms": [{"__tuple__": ["alice", "ClusterAdmin", "cl1"]}, {"__tuple__": ["devs", "UserRole", "vm3"]}, {"__tuple__": ["carol", "SuperUser", "system"]}, {"__tuple__": ["ops", "StorageAdmin", "dc2"]}, {"__tuple__": ["erin", "Ghost", "system"]}]}], "expected": false}, {"args": ["erin", "vm.start", "vm1", {"parents": {"dc1": "system", "cl1": "dc1", "cl2": "dc1", "h1": "cl1", "vm1": "cl1", "vm2": "cl2", "h2": "cl2", "dc2": "system", "cl3": "dc2", "vm3": "cl3"}, "roles": {"SuperUser": ["*"], "ClusterAdmin": ["vm.start", "vm.stop", "host.maintenance"], "UserRole": ["vm.start"], "StorageAdmin": ["domain.create"]}, "groups": {"alice": ["ops"], "bob": ["devs", "ops"]}, "perms": [{"__tuple__": ["alice", "ClusterAdmin", "cl1"]}, {"__tuple__": ["devs", "UserRole", "vm3"]}, {"__tuple__": ["carol", "SuperUser", "system"]}, {"__tuple__": ["ops", "StorageAdmin", "dc2"]}, {"__tuple__": ["erin", "Ghost", "system"]}]}], "expected": false}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-tokens', 9, 'func', 'Срок жизни токенов', 'Модель OAuth-токенов. События идут в хронологическом порядке и бывают трёх видов: ("issue", t, токен, ttl) — токен выдан в момент t и действителен для моментов от t до t + ttl − 1 включительно; ("revoke", t, токен) — токен отозван (отзыв неизвестного токена ничего не делает); ("use", t, токен) — попытка использовать токен. Повторная выдача токена с тем же именем заменяет прежнюю запись целиком, в том числе снимает отзыв. Напишите функцию check_tokens(events): верните список булевых значений — по одному на каждое событие «use», по порядку: True, если токен выдан, не отозван и не истёк в момент использования.', 'def check_tokens(events):
    pass
', 'Храните для токена конец срока и флаг отзыва; тип события — ev[0].', '{"func": "check_tokens", "tests": [{"args": [[]], "expected": []}, {"args": [[{"__tuple__": ["issue", 0, "a", 10]}, {"__tuple__": ["use", 5, "a"]}, {"__tuple__": ["use", 9, "a"]}, {"__tuple__": ["use", 10, "a"]}]], "expected": [true, true, false]}, {"args": [[{"__tuple__": ["use", 1, "x"]}]], "expected": [false]}, {"args": [[{"__tuple__": ["issue", 0, "a", 100]}, {"__tuple__": ["revoke", 3, "a"]}, {"__tuple__": ["use", 4, "a"]}]], "expected": [false]}, {"args": [[{"__tuple__": ["issue", 0, "a", 5]}, {"__tuple__": ["issue", 2, "b", 5]}, {"__tuple__": ["use", 4, "a"]}, {"__tuple__": ["use", 6, "b"]}, {"__tuple__": ["use", 7, "b"]}]], "expected": [true, true, false]}, {"args": [[{"__tuple__": ["issue", 0, "a", 5]}, {"__tuple__": ["revoke", 1, "a"]}, {"__tuple__": ["issue", 2, "a", 5]}, {"__tuple__": ["use", 3, "a"]}]], "expected": [true]}, {"args": [[{"__tuple__": ["revoke", 0, "a"]}, {"__tuple__": ["issue", 1, "a", 5]}, {"__tuple__": ["use", 2, "a"]}]], "expected": [true]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-cert-report', 10, 'func', 'Отчёт о сроках сертификатов', 'Сертификаты образуют цепочки: каждый подписан издателем, и срок действия сертификата не больше срока издателя. Дан список certs из кортежей (имя, дней_осталось, издатель); издатель — имя другого сертификата из списка, а пустая строка или имя, которого в списке нет, означает корень. Эффективный срок сертификата — минимум из его собственного срока и эффективного срока издателя. Напишите функцию cert_report(certs, warn_days, alert_days): для каждого сертификата определите статус по эффективному сроку e: «EXPIRED», если e <= 0; иначе «ALERT», если e <= alert_days; иначе «WARNING», если e <= warn_days; иначе сертификат в отчёт не попадает. Верните список кортежей (имя, статус, e), отсортированный по e по возрастанию, а при равенстве по имени.', 'def cert_report(certs, warn_days, alert_days):
    pass
', 'Словарь имя → (дни, издатель) и рекурсивная eff(name) с запоминанием; корень — когда издателя нет в словаре.', '{"func": "cert_report", "tests": [{"args": [[{"__tuple__": ["ca", 3000, ""]}, {"__tuple__": ["engine", 400, "ca"]}, {"__tuple__": ["host1", 30, "ca"]}, {"__tuple__": ["host2", 5, "ca"]}, {"__tuple__": ["host3", -2, "ca"]}], 30, 7], "expected": [{"__tuple__": ["host3", "EXPIRED", -2]}, {"__tuple__": ["host2", "ALERT", 5]}, {"__tuple__": ["host1", "WARNING", 30]}]}, {"args": [[{"__tuple__": ["ca", 20, ""]}, {"__tuple__": ["engine", 400, "ca"]}, {"__tuple__": ["host1", 300, "engine"]}], 30, 7], "expected": [{"__tuple__": ["ca", "WARNING", 20]}, {"__tuple__": ["engine", "WARNING", 20]}, {"__tuple__": ["host1", "WARNING", 20]}]}, {"args": [[], 30, 7], "expected": []}, {"args": [[{"__tuple__": ["ca", 0, ""]}, {"__tuple__": ["h", 100, "ca"]}], 30, 7], "expected": [{"__tuple__": ["ca", "EXPIRED", 0]}, {"__tuple__": ["h", "EXPIRED", 0]}]}, {"args": [[{"__tuple__": ["h", 10, "missing"]}], 30, 7], "expected": [{"__tuple__": ["h", "WARNING", 10]}]}, {"args": [[{"__tuple__": ["h", 100, "mid"]}, {"__tuple__": ["mid", 50, "ca"]}, {"__tuple__": ["ca", 6, ""]}], 30, 7], "expected": [{"__tuple__": ["ca", "ALERT", 6]}, {"__tuple__": ["h", "ALERT", 6]}, {"__tuple__": ["mid", "ALERT", 6]}]}, {"args": [[{"__tuple__": ["ca", 900, ""]}, {"__tuple__": ["h", 400, "ca"]}], 30, 7], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 18, 'ov18-retention', 11, 'func', 'Хранение резервных копий', 'Политика хранения копий engine-backup. Копии заданы номерами дней days (уникальные целые, порядок произвольный). Параметры: daily — сколько самых свежих копий хранить безусловно, weekly — сколько ещё недель хранить по одной копии. Из оставшихся (более старых) копий неделя копии равна день // 7. Для каждой недели, где есть оставшиеся копии, кандидат — самая свежая копия этой недели. Из кандидатов хранятся копии weekly самых свежих недель. Всё остальное удаляется. Напишите функцию backups_to_delete(days, daily, weekly): верните отсортированный по возрастанию список номеров дней, копии которых нужно удалить.', 'def backups_to_delete(days, daily, weekly):
    pass
', 'sorted(days, reverse=True); первые daily оставьте, по остальным соберите словарь неделя → первый (самый свежий) день.', '{"func": "backups_to_delete", "tests": [{"args": [[], 3, 2], "expected": []}, {"args": [[1, 2, 3], 3, 0], "expected": []}, {"args": [[1, 2, 3, 4, 5], 2, 0], "expected": [1, 2, 3]}, {"args": [[30, 29, 28, 27, 22, 21, 15, 14, 8, 7, 1], 2, 2], "expected": [1, 7, 8, 14, 15, 21, 22]}, {"args": [[30, 29, 28, 27, 22, 21, 15, 14, 8, 7, 1], 2, 3], "expected": [1, 7, 8, 14, 21, 22]}, {"args": [[1, 7, 8, 14, 15, 21, 22, 27, 28, 29, 30], 2, 3], "expected": [1, 7, 8, 14, 21, 22]}, {"args": [[10, 9, 3], 0, 1], "expected": [3, 9]}, {"args": [[5, 4, 3], 1, 10], "expected": [3]}]}');
